<script>
    const jobs=@json($jobs),savedJobs=@json($savedJobs);
    const list=document.getElementById('jobList');
    function renderJobs(items){
        list.innerHTML=items.map(job=>`<article class="job-card"><span class="logo">${job.logo}</span><div><h2>${job.title}</h2><p>${job.company} <strong style="color:#075fe4">✓</strong></p><div class="meta"><span>${job.location}</span><span>•</span><span>${job.posted}</span></div></div><div><div class="badges"><span class="badge">${job.type}</span><span class="badge purple">${job.experience}</span><span class="badge ${job.mode==='Hybrid'?'orange':'blue'}">${job.mode}</span></div><br><button class="btn">View Details</button></div><button class="save">${job.saved?'▣':'▢'}</button></article>`).join('');
    }
    document.getElementById('savedList').innerHTML=savedJobs.map(job=>`<div class="saved-item"><span class="logo">${job.logo}</span><div><h3>${job.title}</h3><p>${job.company}<br>${job.location}</p></div><button class="save">▣</button></div>`).join('');
    document.getElementById('searchInput').addEventListener('input',e=>{const q=e.target.value.toLowerCase();renderJobs(jobs.filter(job=>`${job.title} ${job.company}`.toLowerCase().includes(q)))});
    renderJobs(jobs);
    document.getElementById('userMenuBtn').addEventListener('click',()=>document.getElementById('userMenu').classList.toggle('show'));
</script>
